import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"炼精化气","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-炼精化气.md","filePath":"50-概念资料/dict-炼精化气.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-炼精化气.md"};function d(i,t,h,u,c,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="炼精化气" tabindex="-1">炼精化气 <a class="header-anchor" href="#炼精化气" aria-label="Permalink to &quot;炼精化气&quot;">​</a></h1><blockquote><p>传统：丹道</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>炼精化气是丹道&quot;筑基三关&quot;的第一关——将身体中的精（生理能量）转化为气（能量），使气充足、经脉通畅。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;炼精化气就是筑基，把身体的能量转化成真气。精足了，就化成气；气足了，自然流通经脉。&quot;</p></blockquote><blockquote><p>&quot;炼精化气不是用意念去&#39;炼&#39;的，你只要心平气和、似守非守地观照中丹田，它自然就在炼了。&quot;</p></blockquote><blockquote><p>&quot;百日功灵——坚持一百天，身体一定会有变化。这个变化其实就是炼精化气的过程。&quot;</p></blockquote><h2 id="了空居士的独特观点" tabindex="-1">了空居士的独特观点 <a class="header-anchor" href="#了空居士的独特观点" aria-label="Permalink to &quot;了空居士的独特观点&quot;">​</a></h2><p>了空居士对&quot;炼&quot;字的理解是<strong>自然转化而非刻意操作</strong>。这非常关键——道家的&quot;炼&quot;往往让人联想到用意识去&quot;烧炼&quot;，了空居士说不需要，心平气和本身就是最好的&quot;火候&quot;。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正解</th></tr></thead><tbody><tr><td>炼精化气要控制呼吸</td><td>心平气和自然就炼了</td></tr><tr><td>炼精化气就是禁欲</td><td>节欲不纵欲即可</td></tr><tr><td>要配合复杂的功法</td><td>似守非守的中丹田观照足矣</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-炼气化神">炼气化神</a> — 筑基后的第二关</li><li><a href="/50-概念资料/dict-炼神还虚">炼神还虚</a> — 第三关</li><li><a href="/50-概念资料/dict-丹田">丹田</a> — 炼精化气的核心区域</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-性命双修">性命双修</a></li></ul>',16)])])}const b=a(l,[["render",d]]);export{s as __pageData,b as default};
